25	        dead_controller: PlayerId,
26	        /// Last-known information captured before zone change clears battlefield state.
27	        dead_damaged_by: Vec<ObjectId>,
28	        dead_toughness: i32,
29	        description: String,
30	    },
31	    /// A creature entering the battlefield trigger.
32	    EnteredBattlefield {
33	        object_id: ObjectId,
