129	/// Compute all legal actions for the player who currently needs to act.
130	pub fn legal_actions(state: &GameState, registry: &CardRegistry) -> LegalActions {
131	    if state.is_game_over() {
132	        return LegalActions { actions: vec![], combat_prompt: None, castable_spells: vec![] };
133	    }
134	
135	    // If we're waiting for a specific action (attackers, blockers, discard).
136	    if let Some(awaiting) = &state.awaiting_action {
137	        return match awaiting {
138	            AwaitingAction::DeclareAttackers => {
139	                let active = state.active_player;
140	                let eligible = combat::eligible_attackers(state, active, registry);
141	                let defending = state.opponent(active);
142	                // Find creatures that must attack (e.g., enchanted by Furor of the Bitten).
143	                let must_attack: Vec<ObjectId> = eligible.iter()
144	                    .filter(|&&id| {
145	                        state.has_continuous_effect(id, &|e| {
146	                            match e {
147	                                crate::types::ContinuousEffect::ForceAttack { scope } => Some(scope),
148	                                _ => None,
149	                            }
150	                        }, registry)
151	                    })
152	                    .copied()
153	                    .collect();
154	                LegalActions {
155	                    actions: vec![],
156	                    combat_prompt: Some(crate::actions::CombatPrompt::ChooseAttackers {
157	                        eligible,
158	                        must_attack,
